namespace SoundConvertClient;
public static class CliBroadcast
{
    public static async Task<int> RunAsync(string[] args,Action<object> print){string? Value(string key){int i=Array.IndexOf(args,key);return i>=0&&i+1<args.Length?args[i+1]:null;}string id=Value("--device-id")??throw new ArgumentException("--device-id required");var peers=(await UdpDiscovery.DiscoverPeersAsync(adapterId:Value("--local")??Value("--adapter"))).Where(x=>x.Device.DeviceId==id&&(Value("--adapter") is not string adapter||x.AdapterName==adapter)).ToArray();if(peers.Length!=1)throw new InvalidOperationException($"Expected exactly one UDP broadcast path, found {peers.Length}; select --adapter");var peer=peers[0];
        UdpResult result;if(args.Contains("--udp-apply")){string mode=Value("--mode")??throw new ArgumentException("--mode dhcp|static required");if(mode is not("dhcp" or "static"))throw new ArgumentException("--mode dhcp|static required");var prepared=await UdpDiscovery.PrepareNetworkAsync(peer,mode=="dhcp",Value("--ip"),int.Parse(Value("--prefix")??"24"),Value("--gateway"),mode=="dhcp"?120:30);if(prepared.Status!=0){print(new{ok=false,stage="prepare",status=prepared.Status,reason=prepared.Reason});return 1;}if(prepared.TransactionId is null)throw new InvalidDataException("Missing transaction");print(new{ok=true,stage="prepared",device_id=id,transaction_id=Convert.ToHexString(prepared.TransactionId).ToLowerInvariant(),adapter=peer.AdapterName});result=await UdpDiscovery.ApplyAsync(prepared.Peer,prepared.TransactionId);}
        else{byte[] transaction=Convert.FromHexString(Value("--transaction-id")??throw new ArgumentException("--transaction-id required"));result=args.Contains("--udp-confirm")?await UdpDiscovery.ConfirmAsync(peer,transaction):await UdpDiscovery.RollbackAsync(peer,transaction);}
        print(new{ok=result.Status==0,stage=args[0],status=result.Status,reason=result.Reason,device_id=id,transaction_id=result.TransactionId is null?null:Convert.ToHexString(result.TransactionId).ToLowerInvariant()});return result.Status==0?0:1;
    }
}
